public static class Ui { public static Color Navy=Color.FromArgb(10,11,23), Accent=Color.FromArgb(0,220,164), Light=Color.FromArgb(7,8,17), Text=Color.FromArgb(238,240,250), Card=Color.FromArgb(15,17,34), Muted=Color.FromArgb(145,150,174), Border=Color.FromArgb(37,40,60); public static Button Btn(string text){var b=new Button{Text=text,FlatStyle=FlatStyle.Flat,BackColor=Accent,ForeColor=Color.FromArgb(7,8,17),Font=new Font("Segoe UI",10,FontStyle.Bold),Height=42,Width=150};b.FlatAppearance.BorderSize=0;b.FlatAppearance.MouseOverBackColor=Color.FromArgb(70,240,195);b.Cursor=Cursors.Hand;return b;} public static Label Title(string text){return new Label{Text=text,AutoSize=true,Font=new Font("Segoe UI",22,FontStyle.Bold),ForeColor=Text,Margin=new Padding(0,0,0,15)};} public static void Round(Control c,int radius=12){c.Region=Region.FromHrgn(CreateRoundRectRgn(0,0,c.Width+1,c.Height+1,radius,radius));c.Resize+=(s,e)=>c.Region=Region.FromHrgn(CreateRoundRectRgn(0,0,c.Width+1,c.Height+1,radius,radius));} [System.Runtime.InteropServices.DllImport("Gdi32.dll",EntryPoint="CreateRoundRectRgn")] static extern IntPtr CreateRoundRectRgn(int nLeftRect,int nTopRect,int nRightRect,int nBottomRect,int nWidthEllipse,int nHeightEllipse); }